d1 = {'A':(0,0),'B':(0,11),'C':(1,4),'D':(2,7),'E':(3,1),'F':(3,13),'G':(4,10),'H':(5,6),'I':(5,15)}
ch1 = {'A','B','C','D','I'}
d2 = {'a':(0,12),'b':(1,1),'c':(1,4),'d':(2,9),'e':(4,3),'f':(4,7)}
ch2 = {'a','e','f'}
def analyze(sq, ch):
    ks=list(sq)
    for k in ks:
        r,c=sq[k]
        # nearest other square: min over (dr gap, dc gap) where gap = cells between
        best=None
        for k2 in ks:
            if k2==k: continue
            r2,c2=sq[k2]
            dr = max(0, max(r-r2-2, r2-r-2)+1)  # rows of zeros between
            dc = max(0, max(c-c2-2, c2-c-2)+1)
            d=(dr,dc)
            score = max(dr,dc)  # chebyshev gap
            if best is None or score<best[0]: best=(score,k2,d)
        print(k, sq[k], 'CH' if k in ch else 'ke', 'nn:',best)
analyze(d1,ch1); print('---'); analyze(d2,ch2)
